Ok((sampling_request_output, notify_messages)) => {
    guardian_budget_compacted = false;
    let SamplingRequestResult {
        needs_follow_up: model_needs_follow_up,
        mailbox_preempted,
        last_agent_message: sampling_request_last_agent_message,
    } = sampling_request_output;
    if model_needs_follow_up {
        sess.input_queue
            .accept_mailbox_delivery_for_current_turn(
                &sess.active_turn,
                &turn_context.sub_id,
            )
            .await;
    }
    can_drain_pending_input = true;
    // Process async hooks only after sampling and its tools have finished.
    drain_async_hook_results(&sess, &turn_context, /*before_user_prompt*/ false).await;
    let (has_pending_input, token_status) = async {
        let has_pending_input =
            sess.input_queue.has_pending_input(&sess.active_turn).await;
        let token_status = super::context_window::context_window_token_status(
            sess.as_ref(),
            turn_context.as_ref(),
        )
        .await;
        (has_pending_input, token_status)
    }
    .instrument(trace_span!("run_turn.collect_post_sampling_state"))
    .await;
    let needs_follow_up = model_needs_follow_up || has_pending_input;

if !needs_follow_up {
    last_agent_message = sampling_request_last_agent_message;
    let stop_outcome = run_turn_stop_hooks(
        &sess,
        &step_context,
        stop_hook_active,
        last_agent_message.clone(),
    )
    .await;
    if matches!(
        turn_context.session_source,
        SessionSource::Internal(InternalSessionSource::MemoryConsolidation)
    ) && (stop_outcome.should_block || stop_outcome.should_stop)
    {
        // Do not feed managed rejections back into an unattended memory loop.
        return Err(CodexErr::InvalidRequest(
            "Memory consolidation was rejected by a Stop hook.".to_string(),
        ));
    }
    if stop_outcome.should_block {
        if let Some(hook_prompt_message) = build_hook_prompt_message(
            &stop_outcome.continuation_fragments,
            &sess.item_id_generator,
        ) {
            sess.record_response_item_and_emit_turn_item(
                &turn_context,
                &step_context.settings.model_info,
                hook_prompt_message,
            )
            .await;
            sess.input_queue
                .accept_mailbox_delivery_for_current_turn(
                    &sess.active_turn,
                    &turn_context.sub_id,
                )
                .await;
            stop_hook_active = true;
            continue;
        } else {
            sess.send_event(
                &turn_context,
                EventMsg::Warning(WarningEvent {
                    message: "Stop hook requested continuation without a prompt; ignoring the block.".to_string(),
                }),
            )
            .await;
        }
    }
    if stop_outcome.should_stop {
        break;
    }

pub(crate) fn build_prompt(
    input: Vec<ResponseItem>,
    step_context: &StepContext,
    base_instructions: BaseInstructions,
    incremental_tools: bool,
) -> Prompt {
    let turn_context = &step_context.turn;
    Prompt {
        input,
        tools: if incremental_tools {
            // Hosted tools still require top-level Responses configuration.
            step_context
                .tool_router
                .model_visible_specs()
                .iter()
                .filter(|tool| matches!(tool, ToolSpec::WebSearch { .. }))
                .cloned()
                .collect()
        } else {
            step_context.tool_router.model_visible_specs()
        },
        parallel_tool_calls: true,
        base_instructions: if incremental_tools {
            BaseInstructions {
                text: String::new(),
                provenance: None,
            }
        } else {
            base_instructions
        },
        output_schema: turn_context.final_output_json_schema.clone(),
        output_schema_strict: !crate::guardian::is_basic_session_source(
            &turn_context.session_source,
        ),
        prompt_cache_ttl: turn_context.prompt_cache_ttl,
        cyber_access_program: turn_context.cyber_access_program,
    }
}

let base_instructions = sess.get_prompt_base_instructions().await;

let tool_runtime = ToolCallRuntime::new(
    Arc::clone(&sess),
    Arc::clone(&step_context),
    Arc::clone(&turn_diff_tracker),
);
let _code_mode_worker = sess.services.code_mode_service.start_turn_worker(
    &sess,
    Arc::clone(&step_context),
    Arc::clone(&turn_diff_tracker),
);
let max_retries = turn_context.provider.info().stream_max_retries();
let incremental_tools = sess
    .current_window_uses_incremental_tools(&step_context)
    .await;
record_registration_metrics(
    &step_context.tool_router,
    &step_context.session_telemetry,
    incremental_tools,
);
let mut retry_state = ResponsesStreamRetryState::default();
let mut initial_input = Some(input);
let mut notify_messages = Vec::new();
let mut executed_tool_calls_by_output = HashMap::new();
loop {
    // Running code-mode cells can request review while this response is in flight.
    // Keep the latest received ID until response.created replaces it.
    let first_attempt = initial_input.is_some();
    let history = if let Some(input) = initial_input.take() {
        input
    } else {
        sess.clone_history().await
    };
    let input_item_count = history.raw_items().len();
    let sampling_step_context = Arc::new(StepContext {
        sampled_through_sequence: Some(history.input_sequence()),
        ..step_context.as_ref().clone()
    });
    let mut prompt_input = history
        .for_prompt(
            &step_context.settings.model_info.input_modalities,
            sess.services.image_store.as_ref(),
        )
        .await;
    sess.services
        .executed_tool_calls
        .attach_to_prompt(&mut prompt_input, &mut executed_tool_calls_by_output);
    let mut prompt = build_prompt(
        prompt_input,
        step_context.as_ref(),
        base_instructions.clone(),
        incremental_tools,
    );
    let responses_metadata = sess
        .responses_metadata(step_context.as_ref(), CodexResponsesRequestKind::Turn)
        .await;

let mut draining_for_mailbox = false;
let err = match try_run_sampling_request(
    tool_runtime.clone(),
    Arc::clone(&sess),
    sampling_step_context,
    Arc::clone(&turn_store),
    client_session,
    &responses_metadata,
    Arc::clone(&turn_diff_tracker),
    prompt,
    pending_audio,
    input_item_count,
    cancellation_token.child_token(),
    &mut draining_for_mailbox,
)
.await
{
    Ok(output) => {
        return Ok((output, notify_messages));
    }

let mut stream_request = async |prompt: &Prompt| {
    client_session
        .stream(
            prompt,
            &step_context.settings.model_info,
            &step_context.session_telemetry,
            effort.clone(),
            step_context.settings.reasoning_summary,
            step_context.settings.service_tier.clone(),
            responses_metadata,
            &inference_trace,
        )
        .instrument(trace_span!("stream_request"))
        .await
};
let stream = stream_request(&prompt)
    .or_cancel(&cancellation_token)
    .await?;

let mut in_flight: FuturesOrdered<InFlightFuture<'static>> = FuturesOrdered::new();
let mut needs_follow_up = false;
let mut last_agent_message: Option<String> = None;

let outcome: CodexResult<SamplingRequestResult> = loop {
    if response_completed && resampling.accepted_output.is_empty() {
        if resampling.update_usage_boundary {
            sess.state.lock().await.history.reset_last_usage_boundary();
        }
        break Ok(SamplingRequestResult {
            needs_follow_up,
            mailbox_preempted: *draining_for_mailbox,
            last_agent_message,
        });
    }

if let Some(tool_future) = output_result.tool_future {
    in_flight.push_back(tool_future);
}
if let Some(agent_message) = output_result.last_agent_message {
    last_agent_message = Some(agent_message);
}
needs_follow_up |= output_result.needs_follow_up;

if let Some(false) = end_turn {
    needs_follow_up = true;
}
